// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address actor, uint256 targetBlock, uint256 timeAdvance) public {
        vm.assume(actor != address(0));
        uint256 pay = 10 ether;
        uint256 b = bound(targetBlock, block.number + 1, block.number + 1000);
        uint256 ta = bound(timeAdvance, 1, 1 days);

        vm.deal(actor, pay);

        vm.warp(block.timestamp + ta);
        vm.roll(b);

        vm.prank(actor);
        (bool ok,) = address(c).call{value: pay}("");

        bool shouldBeZero = (b % 15 == 0);
        assertTrue((address(c).balance == 0) == shouldBeZero);
    }
}
